sc_cat_item_producer.script:
var hireName = producer.new_hire.getDisplayValue() || 'New Hire';
current.short_description = 'Onboarding Equipment for ' + hireName;

if (producer.priority.toString().toLowerCase() == 'critical' || producer.priority == '1') {
    current.expedited_shipping = true;
}

if (current.assigned_to.nil()) {
    current.assigned_to = gs.getUserID();
}
